// Vecteur numérique inliné (sûr) + entity_type filtré (anti-injection).
const emb = ($json.data[0].embedding || []).join(',');
const etRaw = $('Appel (Execute Workflow)').item.json.entity_type || '';
const et = etRaw.replace(/[^a-z_]/gi, '');
const entitySql = et ? `'${et}'` : 'null';
const sql = `select coalesce(string_agg(content, E'\n---\n'),'') as context, coalesce(jsonb_agg(jsonb_build_object('document_id',document_id,'similarity',round(similarity::numeric,3))),'[]'::jsonb) as sources from fn_rag_search('[${emb}]'::vector, 6, ${entitySql});`;
return [{ json: { sql } }];

// Dollar-quoting : immunise virgules/guillemets/newlines du contenu généré.
const strip = (s, tag) => String(s == null ? '' : s).split(tag).join('');
const content = $json.choices[0].message.content || '';
const title = strip(content.split('\n')[0].substring(0, 120), '$ttl$');
const body = strip(content, '$bdy$');
const ct = strip($('Appel (Execute Workflow)').item.json.content_type || 'article', '$ct$');
const sources = strip(JSON.stringify($('Recherche RAG (contexte cité)').item.json.sources || []), '$src$');
const target = $('Appel (Execute Workflow)').item.json.target_shopify_id;
const targetSql = (target === undefined || target === null || target === '') ? 'null' : `${parseInt(target, 10)}`;
const cost = ($json.usage.total_tokens / 1000000.0 * 3).toFixed(6);
const sql = `select fn_create_content_proposal($ct$${ct}$ct$, $ttl$${title}$ttl$, $bdy$${body}$bdy$, ${targetSql}, null, ${cost}, $src$${sources}$src$::jsonb) as res;`;
return [{ json: { sql } }];
